formula.beforeSaveCustomScript:
// Calculate working days based on HR record working days
if (startDate && endDate && startDate <= endDate && hrRecordId) {
    // Get employee working days from HR record
    hrWorkingDays = record\attribute('Hr', hrRecordId, 'workingDays');
    hrWorkingHours = record\attribute('Hr', hrRecordId, 'workingHours');

    if (!hrWorkingHours || hrWorkingHours == 0) {
        hrWorkingHours = 40;
    }

    // Count working days for this employee
    workingDaysCount = 0;
    if (hrWorkingDays && array\length(hrWorkingDays) > 0) {
        // Map days to numbers for checking
        currentDate = startDate;
        while (currentDate <= endDate) {
            dayName = datetime\format(currentDate, 'l'); // Full day name
            if (array\includes(hrWorkingDays, dayName)) {
                workingDaysCount = workingDaysCount + 1;
            }
            currentDate = datetime\addDays(currentDate, 1);
        }

        // Calculate daily hours based on actual working days per week
        weeklyWorkingDays = array\length(hrWorkingDays);
        dailyHours = hrWorkingHours / weeklyWorkingDays;
    } else {
        // Fallback to standard calculation (skip weekends)
        totalDays = datetime\diff(startDate, endDate, 'days') + 1;
        weekendDays = 0;
        currentDate = startDate;

        while (currentDate <= endDate) {
            dayOfWeek = datetime\dayOfWeek(currentDate);
            if (dayOfWeek == 0 || dayOfWeek == 6) {
                weekendDays = weekendDays + 1;
            }
            currentDate = datetime\addDays(currentDate, 1);
        }

        workingDaysCount = totalDays - weekendDays;
        dailyHours = hrWorkingHours / 5;
    }

    days = workingDaysCount;

    // Only auto-calculate hours if field is empty or dates changed
    if (!hours || entity\isAttributeChanged('startDate') || entity\isAttributeChanged('endDate') || entity\isAttributeChanged('hrRecordId')) {
        hours = workingDaysCount * dailyHours;
    }
}
